// Embeds skills/postflare/SKILL.md into the CLI (cli/src/skill-content.ts) for `postflare skill install`.
// Runs before every CLI build (npm run cli:build, cli's own build); cli/test/skill.test.ts fails when it is stale.
import { readFileSync, writeFileSync } from "node:fs";

const root = new URL("../", import.meta.url);
const md = readFileSync(new URL("skills/postflare/SKILL.md", root), "utf8");
const out = new URL("cli/src/skill-content.ts", root);
const ts =
  "// Generated by scripts/embed-skill.mjs from skills/postflare/SKILL.md. Do not edit: edit SKILL.md and run `npm run cli:build`.\n" +
  `export const SKILL_MD: string = ${JSON.stringify(md)};\n`;
let current = "";
try {
  current = readFileSync(out, "utf8");
} catch {}
if (current !== ts) writeFileSync(out, ts);
